{"path":"src/lib.rs","edits":[{"oldText":"pub fn run() {
    println!("ulw-bench-fixture running");
}","newText":"use cli::CliConfig;
use std::io::{self, Write};

pub fn run() {
    run_with(&CliConfig::new(), &mut io::stdout()).expect("failed to write to stdout");
}

pub fn run_with<W: Write>(config: &CliConfig, out: &mut W) -> io::Result<()> {
    if config.verbose {
        writeln!(out, "verbose: output = {}", config.output)?;
    }
    writeln!(out, "ulw-bench-fixture running")
}

#[cfg(test)]
mod tests {
    use super::*;

    fn run_to_string(config: &CliConfig) -> String {
        let mut buf = Vec::new();
        run_with(config, &mut buf).unwrap();
        String::from_utf8(buf).unwrap()
    }

    #[test]
    fn test_default_run_is_quiet() {
        let out = run_to_string(&CliConfig::new());
        assert_eq!(out, "ulw-bench-fixture running\n");
    }

    #[test]
    fn test_verbose_run_prints_extra_line_first() {
        let out = run_to_string(&CliConfig::from_args(["--verbose"]));
        let lines: Vec<&str> = out.lines().collect();
        assert_eq!(lines, ["verbose: output = default", "ulw-bench-fixture running"]);
    }
}"}]}

